public void Rotate(int[] nums, int k)
{
    int n = nums.Length;
    k %= n;
    int[] temp = new int[n];
    for (int i = 0; i < n; i++)
        temp[(i + k) % n] = nums[i];
    Array.Copy(temp, nums, n);
}

public void Rotate(int[] nums, int k)
{
    int n = nums.Length;
    k %= n;
    Reverse(nums, 0, n - 1);
    Reverse(nums, 0, k - 1);
    Reverse(nums, k, n - 1);
}

private void Reverse(int[] arr, int start, int end)
{
    while (start < end)
    {
        (arr[start], arr[end]) = (arr[end], arr[start]);
        start++; end--;
    }
}
